document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("dilution-form"),t=document.getElementById("dilution-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("dil-c1").value),i=parseFloat(document.getElementById("dil-v1").value),d=parseFloat(document.getElementById("dil-c2").value),o=parseFloat(document.getElementById("dil-v2").value);if(3!==[!isNaN(n),!isNaN(i),!isNaN(d),!isNaN(o)].filter(Boolean).length)return t.textContent="Enter exactly three parameters.",void 0;isNaN(n)?t.innerHTML=`<b>C₁ =</b> ${(d*o/i).toFixed(4)} mol/L`:isNaN(i)?t.innerHTML=`<b>V₁ =</b> ${(d*o/n).toFixed(4)} L`:isNaN(d)?t.innerHTML=`<b>C₂ =</b> ${(n*i/o).toFixed(4)} mol/L`:isNaN(o)&&(t.innerHTML=`<b>V₂ =</b> ${(n*i/d).toFixed(4)} L`)})});